const http2 = require('node:http2')
const Fastify = require('.')

const big = Buffer.alloc(20 * 1024 * 1024, 0x61)
const app = Fastify({ http2: true })
app.get('/big', (req, reply) => {
  const res = reply.raw
  const t = setInterval(() => {
    console.log('  state: streamDestroyed=%s writableEnded=%s writable=%s', res.stream.destroyed, res.writableEnded, res.writable)
  }, 50)
  setTimeout(() => clearInterval(t), 600).unref()
  reply.header('content-type', 'application/octet-stream').send(big)
})
app.get('/small', (req, reply) => reply.send('ok'))

app.listen({ port: 0 }).then(() => {
  const client = http2.connect('http://localhost:' + app.server.address().port)
  const r1 = client.request({ ':path': '/big' })
  let got = 0
  r1.on('data', d => {
    got += d.length
    if (got > 100000) {
      console.log('cancelling after', got)
      r1.close(http2.constants.NGHTTP2_CANCEL)
    }
  })
  r1.on('error', e => console.log('r1 error', e.code))
  r1.on('close', () => {
    setTimeout(() => {
      const r2 = client.request({ ':path': '/small' })
      let body = ''
      r2.setEncoding('utf8')
      r2.on('data', d => { body += d })
      r2.on('end', () => {
        console.log('second request on same session:', JSON.stringify(body))
        client.close()
        app.close()
      })
      r2.on('error', e => {
        console.log('second request error', e.message)
        client.close()
        app.close()
      })
    }, 300)
  })
  setTimeout(() => {
    console.log('TIMEOUT - session stalled')
    process.exit(1)
  }, 5000)
})

