const h2url = require('h2url')
const Fastify = require('.')

const big = 'é'.repeat(3 * 1024 * 1024) // multi-byte string, > chunk size
const app = Fastify({ http2: true })
app.get('/str', (req, reply) => reply.type('text/plain; charset=utf-8').send(big))
app.get('/trailer', (req, reply) => {
  reply.trailer('etag', () => 'custom-etag')
  reply.type('text/plain; charset=utf-8').send(big)
})

app.listen({ port: 0 }).then(async () => {
  const base = 'http://localhost:' + app.server.address().port

  const str = await h2url.concat({ url: base + '/str' })
  console.log('string payload: status=%s len=%s bodyMatches=%s',
    str.headers[':status'], str.headers['content-length'], str.body === big)

  const head = await h2url.concat({ url: base + '/str', method: 'HEAD' })
  console.log('HEAD: status=%s len=%s emptyBody=%s',
    head.headers[':status'], head.headers['content-length'], head.body === '')

  const tr = await h2url.concat({ url: base + '/trailer' })
  console.log('trailers: status=%s bodyMatches=%s trailers=%j',
    tr.headers[':status'], tr.body === big, tr.trailers)

  await app.close()
})

